CREATE TABLE "MovimientoFinanciero" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "tipo" TEXT NOT NULL, "categoria" TEXT NOT NULL, "importe" REAL NOT NULL, "afectaResultado" BOOLEAN NOT NULL, "afectaCaja" BOOLEAN NOT NULL, "metodoPago" TEXT, "usuarioId" INTEGER NOT NULL, "referenciaTipo" TEXT NOT NULL, "referenciaId" TEXT NOT NULL, "descripcion" TEXT NOT NULL, "creadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MovimientoFinanciero_usuarioId_fkey" FOREIGN KEY ("usuarioId") REFERENCES "Usuario"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "MovimientoFinanciero_creadoEn_categoria_idx" ON "MovimientoFinanciero"("creadoEn", "categoria");
CREATE INDEX "MovimientoFinanciero_referenciaTipo_referenciaId_idx" ON "MovimientoFinanciero"("referenciaTipo", "referenciaId");
